export const RARITY_POINTS = {
  common: 3,
  uncommon: 4,
  rare: 7,
  ultra_rare: 9,
  epic: 10,
  legendary: 12,
  mythic: 14,
  divine: 18,
  prismatic: 100
};

export const CATEGORY_ICONS = {
  typing: "⌨",
  mythic: "⚡",
  divine: "🌟",
};

export const CATEGORIES = ["typing","mythic","divine"];

export const RARITIES = ["common","uncommon","rare","ultra_rare","epic","legendary","mythic","divine","prismatic"];

export function getPoints(rarity) {
  return RARITY_POINTS[rarity] || 0;
}

export function calcTotalPoints(achievementIds) {
  let total = 0;
  for (const id of achievementIds) {
    const a = ACHIEVEMENTS.find(x => x.id === id);
    if (a) total += getPoints(a.rarity);
  }
  return total;
}
